// Package ama implements the "Ask an Expat" thread format (§88, ADR-096).
//
// AMA threads are forum_threads with a non-null ama_config JSONB column.
// This package provides the AMA-specific listing, retrieval, creation, and
// closing endpoints. All SQL is generated by sqlc from
// internal/db/queries/ama.sql — no raw SQL is used (Rule 2).
//
// Ref: japaconnect-engineering/sections/88-ask-an-expat.md
//
//	japaconnect-engineering/adr/ADR-096-ask-an-expat.md
package ama

import (
	"context"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"

	"github.com/jedafe/japa/internal/db"
	"github.com/jedafe/japa/internal/db/gen"
)

// Store is the data-access layer for AMA threads. It uses sqlc-generated
// queries with reader/writer pool separation (read queries → reader, writes
// → writer).
type Store struct {
	read  *gen.Queries
	write *gen.Queries
	db    *db.DB
}

// NewStore creates an AMA store.
func NewStore(database *db.DB) *Store {
	return &Store{
		read:  gen.New(database.Reader),
		write: gen.New(database.Writer),
		db:    database,
	}
}

// AMAThread is a forum thread with AMA config + author info, returned by
// list/get queries. AuthorUsername and AuthorAvatarUrl are interface{} because
// sqlc types them as such (CASE WHEN ... THEN NULL ELSE ... END).
type AMAThread struct {
	ID           pgtype.UUID
	TenantID     pgtype.UUID
	Title        string
	Slug         string
	Body         []byte
	AmaConfig    []byte
	AuthorUserID pgtype.UUID
	AuthorName   string
	AuthorAvatar string
	CreatedAt    pgtype.Timestamptz
	UpdatedAt    pgtype.Timestamptz
}

// CreateAMAParams holds the fields needed to insert an AMA thread.
type CreateAMAParams struct {
	TenantID          pgtype.UUID
	AuthorUserID      pgtype.UUID
	SpaceID           pgtype.UUID
	Title             string
	Slug              string
	Body              []byte
	IsAnonymous       bool
	EditWindowMinutes int32
	AmaConfig         []byte
}

// ListActive returns AMA threads that are still open (closes_at IS NULL or
// closes_at > now()), ordered by most recent first. Cursor-based pagination
// mirrors the forum list pattern (page_size + cursor_created_at). The dest
// and profession filters implement the geo-aware tool pattern (§88 /
// §§79–101): dest matches ama_config->>'host_dest_country_id' and profession
// matches ama_config->>'host_profession' (case-insensitive).
func (s *Store) ListActive(ctx context.Context, tenantID pgtype.UUID, dest, profession string, pageSize int32, cursorCreatedAt pgtype.Timestamptz) ([]AMAThread, error) {
	if pageSize <= 0 {
		pageSize = 20
	}
	if pageSize > 100 {
		pageSize = 100
	}

	rows, err := s.read.ListActiveAMAs(ctx, gen.ListActiveAMAsParams{
		TenantID:        tenantID,
		Dest:            strPtr(dest),
		Profession:      strPtr(profession),
		CursorCreatedAt: cursorCreatedAt,
		PageLimit:       pageSize,
	})
	if err != nil {
		return nil, err
	}

	out := make([]AMAThread, 0, len(rows))
	for _, r := range rows {
		out = append(out, rowToAMAThread(r.ID, r.TenantID, r.Title, r.Slug, r.Body, r.AmaConfig, r.AuthorUserID, r.AuthorUsername, r.AuthorAvatarUrl, r.CreatedAt, r.UpdatedAt))
	}
	return out, nil
}

// GetByID returns a single AMA thread by its ID.
func (s *Store) GetByID(ctx context.Context, id, tenantID pgtype.UUID) (AMAThread, error) {
	r, err := s.read.GetAMAByID(ctx, gen.GetAMAByIDParams{ID: id, TenantID: tenantID})
	if err != nil {
		return AMAThread{}, err
	}
	return rowToAMAThread(r.ID, r.TenantID, r.Title, r.Slug, r.Body, r.AmaConfig, r.AuthorUserID, r.AuthorUsername, r.AuthorAvatarUrl, r.CreatedAt, r.UpdatedAt), nil
}

// GetAuthorID returns the author (author_user_id) of an AMA thread, used by
// the close handler to authorize the host (thread author) to close their own
// AMA without holding forum.ama.moderate (§88 "host or moderator").
func (s *Store) GetAuthorID(ctx context.Context, threadID, tenantID pgtype.UUID) (pgtype.UUID, error) {
	return s.read.GetAMAAuthorID(ctx, gen.GetAMAAuthorIDParams{ID: threadID, TenantID: tenantID})
}

// HasActiveAMA returns true if the user already has an open AMA session
// (closes_at IS NULL or in the future). Enforces the "one active AMA per
// host" rate limit (§88 Rate Limiting).
func (s *Store) HasActiveAMA(ctx context.Context, userID, tenantID pgtype.UUID) (bool, error) {
	return s.read.HasActiveAMA(ctx, gen.HasActiveAMAParams{AuthorUserID: userID, TenantID: tenantID})
}

// CreateAMA inserts a new AMA thread (forum_threads with ama_config) and
// returns the populated row. The service is responsible for validating
// permissions, rate limits, cooldown, and computing closes_at before calling.
func (s *Store) CreateAMA(ctx context.Context, p CreateAMAParams) (AMAThread, error) {
	r, err := s.write.CreateAMA(ctx, gen.CreateAMAParams{
		TenantID:          p.TenantID,
		SpaceID:           p.SpaceID,
		AuthorUserID:      p.AuthorUserID,
		Title:             p.Title,
		Slug:              p.Slug,
		Body:              p.Body,
		IsAnonymous:       p.IsAnonymous,
		EditWindowMinutes: p.EditWindowMinutes,
		AmaConfig:         p.AmaConfig,
	})
	if err != nil {
		return AMAThread{}, err
	}
	return AMAThread{
		ID:           r.ID,
		TenantID:     r.TenantID,
		Title:        r.Title,
		Slug:         r.Slug,
		Body:         r.Body,
		AmaConfig:    r.AmaConfig,
		AuthorUserID: r.AuthorUserID,
		CreatedAt:    r.CreatedAt,
		UpdatedAt:    r.UpdatedAt,
	}, nil
}

// CloseAMA sets the closes_at field in ama_config to now(), closing the AMA.
func (s *Store) CloseAMA(ctx context.Context, threadID, tenantID pgtype.UUID) error {
	return s.write.CloseAMA(ctx, gen.CloseAMAParams{ID: threadID, TenantID: tenantID})
}

// CheckCooldown returns true if the user has created an AMA within the
// cooldown period (default 30 days, configurable via ama_cooldown_days).
func (s *Store) CheckCooldown(ctx context.Context, userID, tenantID pgtype.UUID, cooldownDays int) (bool, error) {
	if cooldownDays <= 0 {
		return false, nil
	}
	return s.read.CheckAMACooldown(ctx, gen.CheckAMACooldownParams{
		AuthorUserID: userID,
		TenantID:     tenantID,
		CooldownDays: int32(cooldownDays),
	})
}

// rowToAMAThread converts sqlc-generated row fields (with interface{} for
// nullable CASE WHEN columns) to the canonical AMAThread struct.
func rowToAMAThread(
	id, tenantID pgtype.UUID, title, slug string, body, amaConfig []byte,
	authorUserID pgtype.UUID, authorUsername, authorAvatar interface{},
	createdAt, updatedAt pgtype.Timestamptz,
) AMAThread {
	t := AMAThread{
		ID:           id,
		TenantID:     tenantID,
		Title:        title,
		Slug:         slug,
		Body:         body,
		AmaConfig:    amaConfig,
		AuthorUserID: authorUserID,
		CreatedAt:    createdAt,
		UpdatedAt:    updatedAt,
	}
	if s, ok := authorUsername.(string); ok {
		t.AuthorName = s
	}
	if s, ok := authorAvatar.(string); ok {
		t.AuthorAvatar = s
	}
	return t
}

// strPtr returns a pointer to s, or nil if s is empty (for sqlc narg params).
func strPtr(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}

// formatTs renders a pgtype.Timestamptz as RFC 3339 UTC, or "" if NULL.
func formatTs(t pgtype.Timestamptz) string {
	if !t.Valid {
		return ""
	}
	return t.Time.UTC().Format(time.RFC3339)
}

// errNoRows is a sentinel for pgx.ErrNoRows, re-exported for the service.
var errNoRows = pgx.ErrNoRows
